function shq(s){
  s=String(s);
  if(/^[A-Za-z0-9_\/:.=@%+-]+$/.test(s)) return s;
  return "'"+s.replace(/'/g,"'\\''")+"'";
}
function parseHeaders(text){
  var out=[];
  String(text||'').split(/\r?\n/).forEach(function(line){
    line=line.trim(); if(!line) return;
    var i=line.indexOf(':');
    if(i<1) throw new Error('无效请求头: '+line);
    out.push({key:line.slice(0,i).trim(), value:line.slice(i+1).trim()});
  });
  return out;
}
function buildCurl(opt){
  opt=opt||{};
  var url=String(opt.url||'').trim();
  if(!url) throw new Error('URL 不能为空');
  var method=(opt.method||'GET').toUpperCase();
  var parts=['curl'];
  if(opt.silent) parts.push('-s');
  if(opt.includeHeaders) parts.push('-i');
  if(opt.followRedirect) parts.push('-L');
  if(opt.insecure) parts.push('-k');
  if(method!=='GET') parts.push('-X '+method);
  var headers=(opt.headers||[]).slice();
  var bodyType=opt.bodyType||'none';
  var body=opt.body!=null?String(opt.body):'';
  if(bodyType==='json' && !headers.some(function(h){return h.key.toLowerCase()==='content-type';}))
    headers.push({key:'Content-Type',value:'application/json'});
  if(bodyType==='form' && !headers.some(function(h){return h.key.toLowerCase()==='content-type';}))
    headers.push({key:'Content-Type',value:'application/x-www-form-urlencoded'});
  headers.forEach(function(h){ parts.push('-H '+shq(h.key+': '+h.value)); });
  if(opt.user) parts.push('-u '+shq(opt.user));
  if(bodyType!=='none' && body) parts.push('-d '+shq(body));
  parts.push(shq(url));
  return parts.join(' \\\n  ');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { shq:shq, parseHeaders:parseHeaders, buildCurl:buildCurl };
}
if (typeof window !== 'undefined') {
  window.CurlForgePure = { shq:shq, parseHeaders:parseHeaders, buildCurl:buildCurl };
}
